// ErrInvalidAmount is returned for an amount that cannot be read.
var ErrInvalidAmount = errors.New("invalid amount")

// ParseMajor reads an amount a person typed in major units ("12.50", "7", "1.250") and returns it in minor units. It takes
// at most the currency's decimal places, and no decimal point at all for JPY.
func ParseMajor(s string, c Currency) (int64, error) {
	if !c.Valid() {
		return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
	}
	d := c.MinorUnits()
	s = strings.TrimSpace(s)
	whole, frac, hasDot := strings.Cut(s, ".")
	if whole == "" || (hasDot && frac == "") || len(frac) > d {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
		}
	}
	for len(frac) < d {
		frac += "0"
	}
	n, err := strconv.ParseInt(whole+frac, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	return n, nil
}

// Format renders an amount for people, with the currency's decimals: "$1,234.50", "-€0.99", "¥1,000", "KWD 1.250".
func Format(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	return sign + symbols[c] + group(whole) + frac
}

// FormatMajor renders an amount in major units with the currency's decimals and no thousands separator: "12.50", "1000",
// "-1.250".
func FormatMajor(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	return sign + strconv.FormatInt(whole, 10) + frac
}

// split separates amount into its sign, its major part and its decimal part (".50", or "" when the currency has none).
func split(amount int64, c Currency) (sign string, whole int64, frac string) {
	if amount < 0 {
		sign, amount = "-", -amount
	}
	d := c.MinorUnits()
	scale := int64(1)
	for i := 0; i < d; i++ {
		scale *= 10
	}
	whole = amount / scale
	if d > 0 {
		frac = fmt.Sprintf(".%0*d", d, amount%scale)
	}
	return sign, whole, frac
}

