func TestParseMajorDecimals(t *testing.T) {
	for _, c := range []struct {
		in   string
		cur  Currency
		want int64
	}{
		{"1000", JPY, 1000},
		{"7", KWD, 7000},
		{"1.250", KWD, 1250},
		{"0.005", KWD, 5},
		{"1.5", KWD, 1500},
		{"12.5", USD, 1250},
	} {
		got, err := ParseMajor(c.in, c.cur)
		if err != nil || got != c.want {
			t.Errorf("ParseMajor(%q, %s) = %d, %v; want %d", c.in, c.cur, got, err, c.want)
		}
	}
	for _, c := range []struct {
		in  string
		cur Currency
	}{
		{"1000.5", JPY}, // no decimal point for JPY
		{"1.0", JPY},
		{"1.", JPY},
		{"1.2345", KWD}, // more decimals than the currency has
		{"1.001", USD},
		{"1 000", JPY}, // spaces inside the number
		{"+1", USD},
		{"-1", KWD},
		{"1,000", KWD},
		{"", KWD},
		{"  ", JPY},
		{".5", KWD},
	} {
		if _, err := ParseMajor(c.in, c.cur); !errors.Is(err, ErrInvalidAmount) {
			t.Errorf("ParseMajor(%q, %s) = %v, want ErrInvalidAmount", c.in, c.cur, err)
		}
	}
}

func TestMinorUnits(t *testing.T) {
	for c, want := range map[Currency]int{USD: 2, EUR: 2, GBP: 2, JPY: 0, KWD: 3} {
		if got := c.MinorUnits(); got != want {
			t.Errorf("%s.MinorUnits() = %d, want %d", c, got, want)
		}
	}
}

