1	// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD), never a
2	// float.
3	package money
4	
5	import (
6		"errors"
7		"fmt"
8		"strconv"
9		"strings"
10	)
11	
12	// Currency is an ISO 4217 currency code.
13	type Currency string
14	
15	// The currencies Tally bills in.
16	const (
17		USD Currency = "USD"
18		EUR Currency = "EUR"
19		GBP Currency = "GBP"
20		JPY Currency = "JPY"
21		KWD Currency = "KWD"
22	)
23	
24	var symbols = map[Currency]string{USD: "$", EUR: "€", GBP: "£", JPY: "¥", KWD: "KWD "}
25	
26	// decimals is the number of decimal places in each currency's minor unit (ISO 4217).
27	var decimals = map[Currency]int{USD: 2, EUR: 2, GBP: 2, JPY: 0, KWD: 3}
28	
29	// Valid reports whether c is a currency Tally bills in.
30	func (c Currency) Valid() bool {
31		_, ok := symbols[c]
32		return ok
33	}
34	
35	// MinorUnits returns the number of decimal places in c's minor unit: 2 for USD, 0 for JPY, 3 for KWD. It is 0 for an
36	// unknown currency.
37	func (c Currency) MinorUnits() int { return decimals[c] }
38	
39	// ErrInvalidAmount is returned for an amount that cannot be read.
40	var ErrInvalidAmount = errors.New("invalid amount")
41	
42	// ParseMajor reads an amount a person typed in major units ("12.50", "7", "1.250") and returns it in minor units. It takes
43	// at most the currency's decimal places, and no decimal point at all for JPY.
44	func ParseMajor(s string, c Currency) (int64, error) {
45		if !c.Valid() {
46			return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
47		}
48		d := c.MinorUnits()
49		s = strings.TrimSpace(s)
50		whole, frac, hasDot := strings.Cut(s, ".")
51		if whole == "" || (hasDot && frac == "") || len(frac) > d {
52			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
53		}
54		for _, r := range whole + frac {
55			if r < '0' || r > '9' {
56				return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
57			}
58		}
59		for len(frac) < d {
60			frac += "0"
61		}
62		n, err := strconv.ParseInt(whole+frac, 10, 64)
63		if err != nil {
64			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
65		}
66		return n, nil
67	}
68	
69	// Format renders an amount for people, with the currency's decimals: "$1,234.50", "-€0.99", "¥1,000", "KWD 1.250".
70	func Format(amount int64, c Currency) string {
71		sign, whole, frac := split(amount, c)
72		return sign + symbols[c] + group(whole) + frac
73	}
74	
75	// FormatMajor renders an amount in major units with the currency's decimals and no thousands separator: "12.50", "1000",
76	// "-1.250".
77	func FormatMajor(amount int64, c Currency) string {
78		sign, whole, frac := split(amount, c)
79		return sign + strconv.FormatInt(whole, 10) + frac
80	}
81	
82	// split separates amount into its sign, its major part and its decimal part (".50", or "" when the currency has none).
83	func split(amount int64, c Currency) (sign string, whole int64, frac string) {
84		if amount < 0 {
85			sign, amount = "-", -amount
86		}
87		d := c.MinorUnits()
88		scale := int64(1)
89		for i := 0; i < d; i++ {
90			scale *= 10
91		}
92		whole = amount / scale
93		if d > 0 {
94			frac = fmt.Sprintf(".%0*d", d, amount%scale)
95		}
96		return sign, whole, frac
97	}
98	
99	// group writes n with a comma between each group of three digits.
100	func group(n int64) string {
101		s := strconv.FormatInt(n, 10)
102		var b strings.Builder
103		for i, r := range s {
104			if i > 0 && (len(s)-i)%3 == 0 {
105				b.WriteByte(',')
106			}
107			b.WriteRune(r)
108		}
109		return b.String()
110	}
111	
112	// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
113	func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }
114	
115	// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
116	func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }
117	
118	// divRound divides and rounds half away from zero.
119	func divRound(num, den int64) int64 {
120		if (num < 0) != (den < 0) {
121			return -((abs(num) + abs(den)/2) / abs(den))
122		}
123		return (abs(num) + abs(den)/2) / abs(den)
124	}
125	
126	func abs(v int64) int64 {
127		if v < 0 {
128			return -v
129		}
130		return v
131	}
